package com.example.incidentapp.util;
import com.example.incidentapp.model.Incidente; import java.text.*; import java.util.*;
public final class SlaUtils { public enum ColorEstado{VERDE,AMARILLO,ROJO,GRIS} public static class Estado{public final ColorEstado color;public final String texto;public final boolean vencidoActivo;Estado(ColorEstado c,String t,boolean v){color=c;texto=t;vencidoActivo=v;}} private SlaUtils(){}
 public static Estado calcular(Incidente i){if(i==null)return new Estado(ColorEstado.GRIS,"SLA no disponible",false);Date inicio=parse(i.getFechaRegistro());if(inicio==null)return new Estado(ColorEstado.GRIS,"SLA sin fecha",false);long limite=horas(i.getPrioridad())*3600000L;String est=i.getEstado()==null?"":i.getEstado();if("Resuelto".equalsIgnoreCase(est)){Date fin=parse(i.getFechaResolucion());long usado=(fin==null?System.currentTimeMillis():fin.getTime())-inicio.getTime();return new Estado(ColorEstado.VERDE,"Resuelto en "+formato(Math.max(0,usado)),false);}if("No Resuelto".equalsIgnoreCase(est)){Date fin=parse(i.getFechaNoResuelto());long usado=(fin==null?System.currentTimeMillis():fin.getTime())-inicio.getTime();long excedido=Math.max(0,usado-limite);return new Estado(ColorEstado.ROJO,"No resuelto · excedido "+formato(excedido),false);}if("Anulado".equalsIgnoreCase(est))return new Estado(ColorEstado.GRIS,"Incidente anulado",false);long restante=inicio.getTime()+limite-System.currentTimeMillis();if(restante<=0)return new Estado(ColorEstado.ROJO,"SLA vencido · "+formato(-restante),true);double proporcion=(double)restante/(double)limite;return new Estado(proporcion<=0.25?ColorEstado.AMARILLO:ColorEstado.VERDE,"SLA restante · "+formato(restante),false);}
 public static boolean estaVencidoActivo(Incidente i){return calcular(i).vencidoActivo;} private static int horas(String p){if("Alta".equalsIgnoreCase(p))return 4;if("Media".equalsIgnoreCase(p))return 24;return 72;} public static String formato(long ms){long s=Math.max(0,ms/1000),h=s/3600,m=(s%3600)/60,ss=s%60;if(h>=24)return String.format(Locale.getDefault(),"%dd %02d:%02d:%02d",h/24,h%24,m,ss);return String.format(Locale.getDefault(),"%02d:%02d:%02d",h,m,ss);} public static Date parse(String v){if(v==null||v.trim().isEmpty())return null;String[] ps={"EEE, dd MMM yyyy HH:mm:ss z","yyyy-MM-dd HH:mm:ss","yyyy-MM-dd'T'HH:mm:ss","yyyy-MM-dd'T'HH:mm:ss.SSSXXX"};for(String p:ps){try{SimpleDateFormat f=new SimpleDateFormat(p,Locale.US);f.setLenient(true);return f.parse(v);}catch(Exception ignored){}}return null;} }
